function figIds(id){
  id=String(id||'').trim();
  const empty={fig:null,bl:null,bo:null};
  if(!id||typeof FIGIDS!=='object'||!FIGIDS)return empty;
  const parse=(fig,raw)=>{
    if(raw==null)return {fig,bl:null,bo:null};
    const s=String(raw),i=s.indexOf(',');
    const bl=i<0?s:s.slice(0,i),bo=i<0?'':s.slice(i+1);
    return {fig,bl:bl||null,bo:bo||null};
  };
  if(/^fig-/i.test(id)){
    const k=id.slice(4);
    return parse(id.replace(/^FIG-/i,'fig-'), FIGIDS[k]!=null?FIGIDS[k]:FIGIDS[id]);
  }
  if(!figIds._bl){
    const idx=Object.create(null);
    for(const k in FIGIDS){
      const rec=parse('fig-'+k,FIGIDS[k]);
      if(!rec.bl)continue;
      const key=rec.bl.toLowerCase();
      (idx[key]||(idx[key]=[])).push(rec);
    }
    figIds._bl=idx;
  }
  const list=figIds._bl[id.toLowerCase()]||[];
  if(!list.length)return {fig:null,bl:id,bo:null};
  if(list.length===1)return {fig:list[0].fig,bl:list[0].bl||id,bo:list[0].bo};
  const bos=[...new Set(list.map(x=>x.bo).filter(Boolean))];
  return {fig:null,bl:list[0].bl||id,bo:bos.length===1?bos[0]:null};
}
